CREATE TABLE personas (id INT AUTO_INCREMENT PRIMARY KEY, active BOOLEAN NOT NULL DEFAULT TRUE, dni VARCHAR(15) NOT NULL UNIQUE, nombre VARCHAR(100) NOT NULL, apellido_paterno VARCHAR(100) NOT NULL, apellido_materno VARCHAR(100) NOT NULL, fecha_nacimiento DATE, telefono VARCHAR(20), genero VARCHAR(20) DEFAULT 'NO_IDENTIFICADO');
CREATE TABLE cuentas_usuario (id INT AUTO_INCREMENT PRIMARY KEY, active BOOLEAN NOT NULL DEFAULT TRUE, username VARCHAR(50) NOT NULL UNIQUE, password_hash VARCHAR(255) NOT NULL, rol VARCHAR(30) NOT NULL, intentos_fallidos INT DEFAULT 0, bloqueada_hasta DATETIME NULL, fecha_ultimo_cambio_password DATETIME NULL, persona_id INT UNIQUE, CONSTRAINT fk_cuenta_persona FOREIGN KEY (persona_id) REFERENCES personas(id), CONSTRAINT chk_rol CHECK (rol IN ('ADMINISTRADOR','DOCENTE','ALUMNO','APODERADO')));
CREATE TABLE registros_auditoria (id INT AUTO_INCREMENT PRIMARY KEY, fecha_hora DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, id_usuario INT, rol VARCHAR(30), modulo VARCHAR(50), entidad VARCHAR(50), id_entidad INT, accion VARCHAR(30) NOT NULL, valor_anterior TEXT, valor_nuevo TEXT, descripcion VARCHAR(255));
CREATE TABLE registros_error (id INT AUTO_INCREMENT PRIMARY KEY, fecha_hora DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, nivel VARCHAR(20) NOT NULL, codigo_error VARCHAR(50), id_usuario INT, metodo_http VARCHAR(10), endpoint VARCHAR(255), codigo_estado INT, mensaje VARCHAR(255), stack_trace TEXT, descripcion VARCHAR(255));
